__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"ikkeLov",{enumerable:!0,get:function(){return l}}),Object.defineProperty(e,"infosider",{enumerable:!0,get:function(){return s}});var t=r(d[0]),n=r(d[1]);const l=['H\xe5ndtere bankkort, PIN-koder eller nettbank','Gi eller h\xe5ndtere medisiner','Personlig stell, som dusj eller p\xe5kledning','Kj\xf8re bil','G\xe5 p\xe5 stige eller tak','Bruke farlig verkt\xf8y, som motorsag eller hekksaks','L\xf8fte tunge ting alene','Ta imot kontanter'],s={personvern:{tittel:'Personvern',ingress:'Slik tar vi vare p\xe5 opplysningene dine. Kort fortalt: vi lagrer bare det vi trenger, og selger aldri noe.',utkast:!0,seksjoner:[{tittel:'Hvem er ansvarlig?',avsnitt:[`Hverdagshelten (ungdomsbedrift) er ansvarlig for opplysningene i appen. Har du sp\xf8rsm\xe5l, kan du skrive til oss i appen eller sende e-post til ${t.kontaktEpost}.`]},{tittel:'Hva lagrer vi, og hvorfor?',punkter:['Navn, e-post og omr\xe5de, s\xe5 du har en egen konto og andre vet hvem som har lagt ut en annonse.','Passordet ditt, kryptert. Ingen i teamet kan lese det.','Annonsene og bildene du legger ut, s\xe5 andre i nabolaget kan se dem.','Det du melder fra om, s\xe5 teamet kan f\xf8lge det opp.']},{tittel:'Dette ber vi aldri om',punkter:['F\xf8dselsnummer','Helseopplysninger eller medisiner','Bankkort eller PIN-kode']},{tittel:'Hvem ser hva?',punkter:['Alle som er logget inn, ser annonsene, navnet ditt og omr\xe5det du har skrevet p\xe5 annonsen.','E-postadressen din vises aldri til andre brukere.','Teamet ser det vi trenger for \xe5 hjelpe deg og f\xf8lge opp hvis noe g\xe5r galt.']},{tittel:'Hvor lagres det?',avsnitt:['Opplysningene lagres hos Supabase p\xe5 servere i EU. Vi har databehandleravtale med alle tjenester vi bruker.']},{tittel:'Hvor lenge?',punkter:['Annonser ligger ute til du sletter dem.','Sletter du kontoen, sletter vi profilen, annonsene og bildene dine med en gang.']},{tittel:'Dine rettigheter',punkter:['Se alt vi har lagret om deg (under \xabMine opplysninger\xbb).','Rette det som er feil.','Slette kontoen din n\xe5r som helst.','Klage til Datatilsynet hvis du mener vi gj\xf8r noe galt.'],avsnitt:['Vi svarer p\xe5 alle sp\xf8rsm\xe5l om personvern innen 30 dager.']},{tittel:'Barn og ungdom',avsnitt:[`Hjelpere under 18 \xe5r m\xe5 ha samtykke fra en foresatt, b\xe5de for \xe5 bruke appen og for \xe5 ta oppdrag. Du m\xe5 v\xe6re minst ${n.regler.minsteAlder} \xe5r.`]},{tittel:'Bestille for andre',avsnitt:['Bestiller du for noen andre, m\xe5 du bekrefte at personen vet om det og har sagt ja.']}]},vilkar:{tittel:'Brukervilk\xe5r',ingress:'Det viktigste du m\xe5 vite n\xe5r du bruker Hverdagshelten.',utkast:!0,seksjoner:[{tittel:'Hva Hverdagshelten er',avsnitt:['Hverdagshelten er en formidler. Vi setter eldre som trenger litt hjelp i kontakt med ungdom i nabolaget som vil hjelpe. Vi sjekker hjelperne og passer p\xe5 at betalingen g\xe5r riktig for seg.']},{tittel:'Hva vi har ansvar for',punkter:['At hjelperne er bekreftet med BankID og godkjent av foresatte og teamet.','At prisen er tydelig f\xf8r du bestiller, og at du f\xe5r kvittering.','At opplysningene dine behandles trygt.','\xc5 f\xf8lge opp raskt hvis du melder fra om noe.']},{tittel:'Hva vi ikke har ansvar for',punkter:['Oppgaver som ikke st\xe5r i bestillingen.','Ting som avtales utenom appen.','Skader som skyldes at noen ikke fulgte reglene under.']},{tittel:'Dette er ikke lov p\xe5 et oppdrag',punkter:l},{tittel:'Pris og betaling',avsnitt:[`Hjelpen koster ${n.priser.timepris} kr per time, og minst 1 time. I tillegg kommer et gebyr p\xe5 ${n.priser.gebyr} kr per bestilling. Ved handling betaler du varene i tillegg, og hjelperen tar bilde av kvitteringen. Du betaler med Vipps etter bes\xf8ket. Ingen kontanter.`]},{tittel:'Avlysning',punkter:[`Avlys gratis fram til ${n.regler.avlysFristTimer} timer f\xf8r bes\xf8ket.`,'Avlyser du senere, ber vi deg ogs\xe5 si fra til oss, s\xe5 hjelperen f\xe5r beskjed.',`Hjelpere kan avlyse i appen fram til ${n.regler.avlysFristTimer} timer f\xf8r. Senere m\xe5 de ringe teamet.`,'Kommer ikke hjelperen, betaler du ingenting, og vi finner en ny hjelper s\xe5 raskt vi kan.']},{tittel:'Regler for ungdom',punkter:[`Du m\xe5 v\xe6re minst ${n.regler.minsteAlder} \xe5r, og foresatte m\xe5 godkjenne.`,'Bare lett arbeid som passer for din alder.',`Ingen oppdrag etter kl. ${n.regler.senestFerdigKl}.`,'Ikke for mange timer i skoleuka. Skolen kommer f\xf8rst.']},{tittel:'Klage',avsnitt:[`Er du misforn\xf8yd, kan du skrive til oss i appen eller sende e-post til ${t.kontaktEpost}. Vi svarer innen tre arbeidsdager.`]}]},trygghet:{tittel:'Slik sjekker vi hjelperne',ingress:'Alle som f\xe5r merket \xabSjekket av Hverdagshelten\xbb, har g\xe5tt gjennom dette.',seksjoner:[{tittel:'F\xf8r de kan ta oppdrag',punkter:['De bekrefter hvem de er med BankID.','En foresatt godkjenner dem, hvis de er under 18 \xe5r.','De m\xf8ter teamet personlig, for eksempel p\xe5 en hjelperkveld.','De g\xe5r gjennom retningslinjene og en kort quiz.']},{tittel:'Under bes\xf8ket',punkter:['Du ser navn, alder og bilde av hjelperen f\xf8r bes\xf8ket.','Telefonnummer vises bare mens dere har en avtale.','All betaling skjer i appen. Gi aldri kontanter, bankkort eller PIN-kode.','Det f\xf8rste bes\xf8ket kan gjerne v\xe6re med en p\xe5r\xf8rende til stede.']},{tittel:'Hvis noe skjer',punkter:['Ring 113 hvis noen er skadet eller blir akutt syk.','Trykk \xabMeld fra om noe\xbb p\xe5 avtalen hvis noe ikke f\xf8ltes riktig. Vi tar det alltid p\xe5 alvor.']}]},betaling:{tittel:'Betaling',ingress:'Enkelt og trygt, med Vipps.',seksjoner:[{tittel:'Slik betaler du',punkter:[`Hjelpen koster ${n.priser.timepris} kr per time, og et gebyr p\xe5 ${n.priser.gebyr} kr per bestilling.`,'Du ser prisen f\xf8r du sender bestillingen.','Du betaler med Vipps etter at bes\xf8ket er gjennomf\xf8rt.','Kvitteringen ligger i appen, og kommer p\xe5 e-post.']},{tittel:'Handling',avsnitt:['Varene betaler du i tillegg. Hjelperen tar bilde av kvitteringen fra butikken, s\xe5 du ser hva det kostet.']},{tittel:'P\xe5r\xf8rende kan betale',avsnitt:['Har du lagt til p\xe5r\xf8rende, kan de betale for deg. De f\xe5r en betalingsforesp\xf8rsel i Vipps.']},{tittel:'Ingen kontanter',avsnitt:['All betaling g\xe5r gjennom appen. Da er det trygt for alle.']}]},retningslinjer:{tittel:'Slik er du en god hverdagshelt',ingress:'Det viktigste er \xe5 v\xe6re hyggelig, rolig og til \xe5 stole p\xe5.',seksjoner:[{tittel:'N\xe5r du kommer',punkter:['Kom presis. Blir du forsinket, ring og si fra.','Ring p\xe5 eller bank, og si hvem du er: \xabHei, jeg heter Emil, fra Hverdagshelten.\xbb','Snakk tydelig og ikke for fort. Mange h\xf8rer d\xe5rlig.']},{tittel:'Mobilhjelp',punkter:['La den eldre trykke selv. Forklar ett steg om gangen.','Skriv gjerne ned stegene p\xe5 et ark.','Be aldri om passord eller PIN-kode.']},{tittel:'P\xe5 tur',punkter:['G\xe5 i den andres tempo, og tilby armen din.','Velg flate veier uten is og trapper.','Ta pauser p\xe5 benker underveis.']},{tittel:'Dette skal du ikke gj\xf8re',punkter:l},{tittel:'Hvis noe skjer',punkter:['Ring 113 hvis noen er skadet eller blir akutt syk.','Ring s\xe5 teamet, og en foresatt.','F\xf8les noe ubehagelig, kan du alltid g\xe5. Meld fra til oss etterp\xe5.']}]}}},850,[799,779]);